    'legal_terms_s3_title' => '3. Acesso ao serviço',
    'legal_terms_s3_1_title' => '3.1 Registo',
    'legal_terms_s3_1_p' => 'O acesso ao Serviço requer a criação de uma conta. O Utilizador deve fornecer informações exatas e completas, nomeadamente um endereço de email válido.',
    'legal_terms_s3_2_title' => '3.2 Condições de elegibilidade',
    'legal_terms_s3_2_p' => 'O Serviço destina-se a profissionais (empresas, trabalhadores independentes, profissões liberais). O Utilizador declara:',
    'legal_terms_s3_2_li1' => 'Ser maior de idade e juridicamente capaz',
    'legal_terms_s3_2_li2' => 'Atuar no âmbito da sua atividade profissional',
    'legal_terms_s3_2_li3' => 'Dispor das autorizações necessárias para utilizar o Serviço',
    'legal_terms_s3_3_title' => '3.3 Segurança da conta',
    'legal_terms_s3_3_p' => 'O Utilizador é responsável pela confidencialidade das suas credenciais de acesso. Qualquer utilização da sua conta é considerada efetuada por ele. Deve informar imediatamente a faktur.lu de qualquer utilização não autorizada.',

    'legal_terms_s4_title' => '4. Descrição do serviço',
    'legal_terms_s4_p' => 'faktur.lu é um software de faturação online (SaaS) em conformidade com os requisitos luxemburgueses e europeus, oferecendo nomeadamente:',
    'legal_terms_s4_li1' => 'Criação e gestão de faturas, orçamentos e notas de crédito',
    'legal_terms_s4_li2' => 'Gestão de clientes e contactos',
    'legal_terms_s4_li3' => 'Exportação FAIA em conformidade com a AED Luxembourg',
    'legal_terms_s4_li4' => 'Controlo de tempo e geração de faturas',
    'legal_terms_s4_li5' => 'Envio de faturas por email',
    'legal_terms_s4_li6' => 'Painel e estatísticas',
    'legal_terms_s4_li7' => 'Acesso seguro para contabilistas',

    'legal_terms_s5_title' => '5. Subscrições e preços',
    'legal_terms_s5_1_title' => '5.1 Planos de subscrição',
    'legal_terms_s5_1_p' => 'O Serviço oferece vários planos:',
    'legal_terms_s5_plan1_title' => 'Descoberta (Gratuito)',
    'legal_terms_s5_plan1_desc' => 'Funcionalidades limitadas, ideal para testar o serviço.',
    'legal_terms_s5_plan2_title' => 'Profissional',
    'legal_terms_s5_plan2_desc' => 'Funcionalidades completas para trabalhadores independentes e PME. Preço apresentado na página de preços.',
    'legal_terms_s5_2_title' => '5.2 Preços',
    'legal_terms_s5_2_p1' => 'Os preços são indicados em euros sem impostos no site. O IVA aplicável será adicionado no momento do pagamento de acordo com a taxa em vigor no Luxemburgo (17%).',
    'legal_terms_s5_2_p2' => 'O Prestador reserva-se o direito de alterar os seus preços a qualquer momento. As alterações de preços serão notificadas por email pelo menos 30 dias antes da sua entrada em vigor e aplicar-se-ão à próxima renovação da subscrição.',
    'legal_terms_s5_3_title' => '5.3 Duração e renovação',
    'legal_terms_s5_3_p' => 'As subscrições são contratadas por uma duração mensal ou anual à escolha do Utilizador. São renovadas automaticamente por tácita recondução no final de cada período, salvo rescisão em conformidade com o artigo 13.',
    'legal_terms_s5_4_title' => '5.4 Período de teste',
    'legal_terms_s5_4_p' => 'Pode ser oferecido um período de teste gratuito. No final deste período, a subscrição torna-se paga salvo rescisão. O Utilizador será informado antes do final do período de teste.',

    'legal_terms_s6_title' => '6. Pagamento',
    'legal_terms_s6_1_title' => '6.1 Meios de pagamento',
    'legal_terms_s6_1_p' => 'O pagamento é efetuado por cartão bancário (Visa, Mastercard, American Express) através da plataforma segura Stripe. As transações são encriptadas e em conformidade com as normas PCI-DSS.',
    'legal_terms_s6_2_title' => '6.2 Faturação',
    'legal_terms_s6_2_p' => 'Uma fatura eletrónica é emitida e disponibilizada na área do cliente após cada pagamento. Pode também ser enviada por email a pedido.',
    'legal_terms_s6_3_title' => '6.3 Falta de pagamento',
    'legal_terms_s6_3_p' => 'Em caso de falha de pagamento, o Utilizador será notificado e disporá de um prazo de 7 dias para regularizar. Após este prazo, o acesso às funcionalidades pagas será suspenso. Os dados serão conservados durante mais 30 dias antes de eventual eliminação.',
    'legal_terms_s6_4_title' => '6.4 IVA',
    'legal_terms_s6_4_p' => 'Para clientes profissionais estabelecidos noutro Estado-Membro da UE com um número de IVA intracomunitário válido, o IVA não será cobrado (autoliquidação). O Cliente deverá então declarar o IVA no seu país.',

    'legal_terms_s7_title' => '7. Direito de retratação',
    'legal_terms_s7_warn_title' => 'Informação importante para consumidores',
    'legal_terms_s7_warn_p' => 'Em conformidade com o artigo L. 221-28 do Código de Consumo francês e as disposições equivalentes do direito luxemburguês, o direito de retratação não se aplica aos contratos de fornecimento de conteúdo digital não fornecido num suporte material cuja execução tenha começado com o consentimento prévio expresso do consumidor.',
    'legal_terms_s7_p1' => 'Ao subscrever uma subscrição paga, o Utilizador reconhece que:',
    'legal_terms_s7_li1' => 'Solicita expressamente a execução imediata do serviço',
    'legal_terms_s7_li2' => 'Renuncia expressamente ao seu direito de retratação de 14 dias a partir do momento em que o acesso ao serviço pago é ativado',
    'legal_terms_s7_p2' => 'No entanto, para as subscrições anuais, pode ser concedido um reembolso prorata temporis mediante pedido nos primeiros 30 dias após a subscrição, sujeito a uma utilização razoável do serviço.',

    'legal_terms_s8_title' => '8. Obrigações do utilizador',
    'legal_terms_s8_p' => 'O Utilizador compromete-se a:',
    'legal_terms_s8_li1' => 'Fornecer informações exatas no momento do registo e mantê-las atualizadas',
    'legal_terms_s8_li2' => 'Utilizar o Serviço de acordo com a sua finalidade (faturação profissional)',
    'legal_terms_s8_li3' => 'Não utilizar o Serviço para fins ilícitos ou contrários à ordem pública',
    'legal_terms_s8_li4' => 'Manter a confidencialidade das suas credenciais de acesso',
    'legal_terms_s8_li5' => 'Respeitar a legislação fiscal e contabilística aplicável à sua atividade',
    'legal_terms_s8_li6' => 'Não tentar comprometer a segurança ou o funcionamento do Serviço',
    'legal_terms_s8_li7' => 'Não revender ou sublicenciar o acesso ao Serviço',

    'legal_terms_s9_title' => '9. Obrigações da faktur.lu',
    'legal_terms_s9_1_title' => '9.1 Disponibilidade do serviço',
    'legal_terms_s9_1_p1' => 'O Prestador compromete-se a implementar os meios necessários para garantir a disponibilidade do Serviço 24h/24 e 7d/7, com um objetivo de disponibilidade de 99,5% (excluindo manutenção programada).',
    'legal_terms_s9_1_p2' => 'As interrupções para manutenção serão, na medida do possível, programadas fora do horário comercial e anunciadas previamente.',
    'legal_terms_s9_2_title' => '9.2 Suporte',
    'legal_terms_s9_2_p_before' => 'Um suporte técnico está disponível por email em',
    'legal_terms_s9_2_p_after' => '. O tempo de resposta varia consoante o plano de subscrição.',
    'legal_terms_s9_3_title' => '9.3 Segurança e backup',
    'legal_terms_s9_3_p' => 'O Prestador implementa medidas de segurança em conformidade com os padrões da indústria e efetua backups regulares dos dados.',

    'legal_terms_s10_title' => '10. Dados e propriedade',
    'legal_terms_s10_1_title' => '10.1 Propriedade dos dados',
    'legal_terms_s10_1_p' => 'O Utilizador permanece proprietário de todos os dados que introduz no Serviço (faturas, informações de clientes, etc.). O Prestador não adquire nenhum direito sobre estes dados.',
    'legal_terms_s10_2_title' => '10.2 Licença de utilização',
    'legal_terms_s10_2_p' => 'O Utilizador concede ao Prestador uma licença limitada para processar os seus dados unicamente no âmbito do fornecimento do Serviço.',
    'legal_terms_s10_3_title' => '10.3 Exportação dos dados',
    'legal_terms_s10_3_p' => 'O Utilizador pode a qualquer momento exportar os seus dados em formatos padrão (PDF, CSV, FAIA XML).',
    'legal_terms_s10_4_title' => '10.4 Proteção dos dados',
    'legal_terms_s10_4_p_before' => 'O tratamento de dados pessoais é regido pela nossa',
    'legal_terms_s10_4_link' => 'Política de privacidade',
    'legal_terms_s10_4_p_after' => '.',

    'legal_terms_s10_5_title' => '10.5 Subcontratação RGPD (DPA)',
    'legal_terms_s10_5_p_before' => 'Quando o Utilizador atua como responsável pelo tratamento ao abrigo do Regulamento (UE) 2016/679 (RGPD) e o faktur.lu trata dados pessoais por sua conta, as partes acordam que o ',
    'legal_terms_s10_5_link' => 'Acordo de tratamento de dados (DPA)',
    'legal_terms_s10_5_p_after' => ', consultável a qualquer momento no site, faz parte integrante dos presentes Termos. Ao aceitar os Termos, o Utilizador aceita igualmente o DPA na sua versão em vigor. Pode ser efetuada uma assinatura manuscrita separada a pedido para Utilizadores que dela necessitem para a sua própria conformidade (nomeadamente fiduciárias e clientes sujeitos a auditoria).',

    'legal_terms_s11_title' => '11. Propriedade intelectual',
    'legal_terms_s11_p1' => 'O Serviço, incluindo o seu código-fonte, a sua interface, as suas funcionalidades, o seu design, as suas marcas e logótipos, é propriedade exclusiva do Prestador ou dos seus parceiros.',
    'legal_terms_s11_p2' => 'A subscrição confere apenas um direito de utilização pessoal, não exclusivo e não transferível do Serviço pela duração da subscrição.',

    'legal_terms_s12_title' => '12. Limitação de responsabilidade',
    'legal_terms_s12_1_title' => '12.1 Garantias',
    'legal_terms_s12_1_p' => 'O Prestador compromete-se a fornecer o Serviço com diligência. No entanto, o Serviço é fornecido "tal como está" e o Prestador não garante que corresponderá a todas as necessidades específicas do Utilizador.',
    'legal_terms_s12_2_title' => '12.2 Limitação',
    'legal_terms_s12_2_p1' => 'A responsabilidade do Prestador está limitada aos danos diretos e não poderá exceder o montante das quantias pagas pelo Utilizador nos últimos 12 meses.',
    'legal_terms_s12_2_p2' => 'O Prestador não pode ser responsabilizado por:',
    'legal_terms_s12_2_li1' => 'Danos indiretos (perda de volume de negócios, prejuízo comercial, etc.)',
    'legal_terms_s12_2_li2' => 'A exatidão dos dados introduzidos pelo Utilizador',
    'legal_terms_s12_2_li3' => 'A conformidade fiscal das faturas emitidas pelo Utilizador',
    'legal_terms_s12_2_li4' => 'Interrupções devidas a terceiros (alojador, ISP, etc.)',
    'legal_terms_s12_2_li5' => 'Casos de força maior',
    'legal_terms_s12_3_title' => '12.3 Responsabilidade do Utilizador',
    'legal_terms_s12_3_p' => 'O Utilizador é o único responsável pela conformidade das suas faturas com a regulamentação fiscal aplicável. O Serviço é uma ferramenta que facilita a faturação mas não constitui aconselhamento fiscal ou jurídico.',

    'legal_terms_s13_title' => '13. Rescisão',
    'legal_terms_s13_1_title' => '13.1 Rescisão pelo Utilizador',
    'legal_terms_s13_1_p1' => 'O Utilizador pode rescindir a sua subscrição a qualquer momento a partir da sua área de cliente. A rescisão produzirá efeitos no final do período em curso. O Utilizador mantém o acesso ao Serviço até essa data.',
    'legal_terms_s13_1_p2' => 'As quantias já pagas não são reembolsáveis, salvo disposição contrária prevista no artigo 7.',
    'legal_terms_s13_2_title' => '13.2 Rescisão pelo Prestador',
    'legal_terms_s13_2_p' => 'O Prestador pode rescindir a subscrição em caso de:',
    'legal_terms_s13_2_li1' => 'Violação dos presentes Termos',
    'legal_terms_s13_2_li2' => 'Falta de pagamento não regularizada',
    'legal_terms_s13_2_li3' => 'Utilização fraudulenta ou abusiva do Serviço',
    'legal_terms_s13_2_li4' => 'Cessação de atividade do Serviço (com aviso prévio de 3 meses)',
    'legal_terms_s13_3_title' => '13.3 Consequências da rescisão',
    'legal_terms_s13_3_p' => 'Após a rescisão, o Utilizador dispõe de 30 dias para exportar os seus dados. Após este prazo, os dados poderão ser eliminados, sujeitos às obrigações legais de conservação.',

    'legal_terms_s14_title' => '14. Modificações dos Termos',
    'legal_terms_s14_p1' => 'O Prestador reserva-se o direito de modificar os presentes Termos. As modificações serão notificadas por email e/ou por afixação no Serviço pelo menos 30 dias antes da sua entrada em vigor.',
    'legal_terms_s14_p2' => 'A utilização continuada do Serviço após a entrada em vigor das modificações vale como aceitação dos novos Termos. Em caso de desacordo, o Utilizador pode rescindir a sua subscrição.',

    'legal_terms_s15_title' => '15. Lei aplicável e jurisdição',
    'legal_terms_s15_p1' => 'Os presentes Termos são regidos pelo direito luxemburguês.',
    'legal_terms_s15_p2' => 'Em caso de litígio, as partes esforçar-se-ão por encontrar uma solução amigável. Em falta, os tribunais do Luxemburgo serão os únicos competentes.',
    'legal_terms_s15_p3_label' => 'Mediação:',
    'legal_terms_s15_p3_text' => 'Em conformidade com a regulamentação europeia, em caso de litígio não resolvido, o consumidor pode recorrer gratuitamente ao serviço de mediação. Plataforma de resolução em linha de litígios:',

    'legal_terms_s16_title' => '16. Contacto',
    'legal_terms_s16_p' => 'Para qualquer questão relativa a estes Termos:',
    'legal_terms_s16_email_label' => 'Email:',
    'legal_terms_s16_address_label' => 'Endereço:',
    'legal_terms_s16_address_value' => 'Alexandre Beaudier, 13 Rue du Stade John F. Kennedy, L-3502 Dudelange, Luxembourg',

    'legal_terms_link_mentions' => 'Avisos legais',
    'legal_terms_link_privacy' => 'Política de privacidade',
    'legal_terms_link_cookies' => 'Política de cookies',

