    'legal_mentions_s3_p1' => 'Todo o conteúdo do site faktur.lu (textos, imagens, gráficos, logótipo, ícones, software, etc.) é propriedade exclusiva de Alexandre Beaudier ou dos seus parceiros, salvo indicação em contrário.',
    'legal_mentions_s3_p2' => 'Qualquer reprodução, representação, modificação, publicação, adaptação total ou parcial dos elementos do site, por qualquer meio ou processo utilizado, é proibida sem a autorização prévia por escrito de Alexandre Beaudier.',
    'legal_mentions_s3_p3' => 'Qualquer exploração não autorizada do site ou de qualquer um dos seus elementos será considerada constitutiva de contrafação e processada de acordo com as disposições do direito luxemburguês.',
    'legal_mentions_s4_title' => '4. Proteção de dados pessoais',
    'legal_mentions_s4_p1' => 'Em conformidade com o Regulamento Geral sobre a Proteção de Dados (RGPD) e a lei luxemburguesa de 1 de agosto de 2018 relativa à proteção de dados pessoais, dispõe de direitos sobre os seus dados pessoais.',
