    'legal_cookies_seo_title' => 'Política de cookies | faktur.lu',
    'legal_cookies_seo_description' => 'Política de utilização de cookies em faktur.lu. Tipos de cookies utilizados e gestão das suas preferências.',
    'legal_cookies_h1' => 'Política de cookies',
    'legal_cookies_last_updated' => 'Última atualização:',
    'legal_cookies_last_updated_date' => '9 de fevereiro de 2026',
    'legal_cookies_toc_title' => 'Índice',
    'legal_cookies_toc_1' => '1. O que é um cookie?',
    'legal_cookies_toc_2' => '2. Cookies utilizados',
