    'legal_cookies_toc_6' => '6. Contacto',
    'legal_cookies_s1_title' => '1. O que é um cookie?',
    'legal_cookies_s1_p1' => 'Um cookie é um pequeno ficheiro de texto colocado no seu dispositivo (computador, tablet, smartphone) ao visitar um sítio web. Permite ao sítio memorizar informações sobre a sua visita, como as suas preferências de idioma ou o seu estado de ligação.',
    'legal_cookies_s1_p2' => 'Os cookies podem ser colocados pelo sítio que visita ("cookies próprios") ou por serviços de terceiros ("cookies de terceiros").',
    'legal_cookies_s2_title' => '2. Cookies utilizados pelo faktur.lu',
    'legal_cookies_s2_1_title' => '2.1 Cookies estritamente necessários',
    'legal_cookies_s2_1_p' => 'Estes cookies são indispensáveis ao funcionamento do sítio. Não podem ser desativados.',
    'legal_cookies_table_cookie' => 'Cookie',
    'legal_cookies_table_purpose' => 'Finalidade',
    'legal_cookies_table_duration' => 'Duração',
    'legal_cookies_s2_1_row1_purpose' => 'Identificação da sessão do utilizador',
    'legal_cookies_s2_1_row1_duration' => '2 horas',
    'legal_cookies_s2_1_row2_purpose' => 'Proteção contra ataques CSRF',
    'legal_cookies_s2_1_row2_duration' => '2 horas',
    'legal_cookies_s2_1_row3_purpose' => 'Manutenção da ligação (se "Lembrar-me")',
    'legal_cookies_s2_1_row3_duration' => '30 dias',
    'legal_cookies_s2_2_title' => '2.2 Cookies funcionais',
    'legal_cookies_s2_2_p' => 'Estes cookies permitem melhorar a sua experiência de utilizador memorizando as suas preferências.',
    'legal_cookies_s2_2_row1_purpose' => 'Memorização do idioma preferido',
    'legal_cookies_s2_2_row1_duration' => '1 ano',
    'legal_cookies_s2_2_row2_purpose' => 'Memorização do modo de visualização (claro/escuro)',
    'legal_cookies_s2_2_row2_duration' => '1 ano',
    'legal_cookies_s2_no_tracking_title' => 'Sem cookies de rastreamento',
    'legal_cookies_s2_no_tracking_p' => 'O faktur.lu não utiliza cookies publicitários ou de rastreamento comportamental. Não vendemos os seus dados a terceiros.',
    'legal_cookies_s3_title' => '3. Cookies de terceiros',
